@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  color-scheme: light;

  /* ===========================================
     FIGMA DESIGN TOKENS - Primitives (oklch)
     =========================================== */

  /* Blue Palette */
  --blue-50: oklch(0.99 0.01 264);
  --blue-100: oklch(0.98 0.01 264);
  --blue-150: oklch(0.95 0.03 254);
  --blue-200: oklch(0.91 0.05 254);
  --blue-250: oklch(0.85 0.07 254);
  --blue-300: oklch(0.79 0.10 254);
  --blue-350: oklch(0.71 0.14 254);
  --blue-400: oklch(0.62 0.17 254);
  --blue-450: oklch(0.53 0.20 264);
  --blue-500: oklch(0.45 0.21 264);
  --blue-550: oklch(0.40 0.16 264);
  --blue-600: oklch(0.35 0.14 264);
  --blue-650: oklch(0.30 0.12 264);
  --blue-700: oklch(0.28 0.11 264);
  --blue-750: oklch(0.24 0.09 264);
  --blue-800: oklch(0.20 0.08 264);
  --blue-850: oklch(0.15 0.06 264);

  /* Grey Palette */
  --grey-50: oklch(1.00 0 0);
  --grey-100: oklch(0.98 0.00 264);
  --grey-150: oklch(0.97 0.00 264);
  --grey-200: oklch(0.96 0.00 264);
  --grey-250: oklch(0.94 0.01 250);
  --grey-300: oklch(0.91 0.01 250);
  --grey-350: oklch(0.88 0.01 250);
  --grey-400: oklch(0.85 0.01 250);
  --grey-450: oklch(0.81 0.01 250);
  --grey-500: oklch(0.77 0.01 250);
  --grey-550: oklch(0.72 0.01 250);
  --grey-600: oklch(0.65 0.01 250);
  --grey-650: oklch(0.61 0.01 250);
  --grey-700: oklch(0.57 0.01 250);
  --grey-750: oklch(0.52 0.01 250);
  --grey-800: oklch(0.48 0.01 250);
  --grey-850: oklch(0.43 0.01 250);
  --grey-900: oklch(0.38 0.01 250);
  --grey-950: oklch(0.32 0.01 250);
  --grey-1000: oklch(0.27 0.01 250);
  --grey-1050: oklch(0.23 0.01 250);
  --grey-1100: oklch(0.18 0.01 250);

  /* Green Palette */
  --green-50: oklch(0.98 0.01 145);
  --green-100: oklch(0.96 0.02 145);
  --green-200: oklch(0.89 0.05 150);
  --green-300: oklch(0.77 0.10 150);
  --green-400: oklch(0.67 0.13 150);
  --green-500: oklch(0.54 0.13 150);
  --green-600: oklch(0.47 0.11 150);
  --green-700: oklch(0.40 0.09 150);
  --green-800: oklch(0.33 0.07 150);
  --green-900: oklch(0.27 0.05 150);

  /* Red Palette */
  --red-50: oklch(0.98 0.01 25);
  --red-100: oklch(0.95 0.03 25);
  --red-200: oklch(0.86 0.08 20);
  --red-300: oklch(0.70 0.15 20);
  --red-400: oklch(0.60 0.19 22);
  --red-500: oklch(0.50 0.19 25);
  --red-600: oklch(0.43 0.16 25);
  --red-700: oklch(0.36 0.13 25);
  --red-800: oklch(0.29 0.10 25);
  --red-900: oklch(0.22 0.07 25);

  /* Orange Palette */
  --orange-50: oklch(0.99 0.01 60);
  --orange-100: oklch(0.95 0.04 60);
  --orange-200: oklch(0.87 0.10 60);
  --orange-300: oklch(0.77 0.15 55);
  --orange-400: oklch(0.70 0.17 50);
  --orange-500: oklch(0.65 0.18 50);
  --orange-600: oklch(0.55 0.15 50);
  --orange-700: oklch(0.45 0.12 50);
  --orange-800: oklch(0.36 0.09 50);
  --orange-900: oklch(0.27 0.06 50);

  /* Denim Palette */
  --denim-100: oklch(0.92 0.05 254);
  --denim-200: oklch(0.81 0.08 254);
  --denim-300: oklch(0.70 0.11 254);
  --denim-400: oklch(0.59 0.14 254);
  --denim-500: oklch(0.46 0.15 254);
  --denim-600: oklch(0.38 0.12 254);
  --denim-700: oklch(0.31 0.09 254);
  --denim-800: oklch(0.21 0.06 254);
  --denim-900: oklch(0.16 0.04 254);

  /* Azure Palette */
  --azure-100: oklch(0.94 0.04 230);
  --azure-200: oklch(0.87 0.08 230);
  --azure-300: oklch(0.80 0.11 230);
  --azure-400: oklch(0.74 0.13 230);
  --azure-500: oklch(0.67 0.15 230);
  --azure-600: oklch(0.54 0.12 230);
  --azure-700: oklch(0.43 0.09 230);
  --azure-800: oklch(0.28 0.06 230);
  --azure-900: oklch(0.21 0.04 230);

  /* Green Haze Palette */
  --green-haze-100: oklch(0.95 0.05 165);
  --green-haze-200: oklch(0.90 0.09 165);
  --green-haze-300: oklch(0.84 0.12 165);
  --green-haze-400: oklch(0.79 0.14 165);
  --green-haze-500: oklch(0.73 0.16 165);
  --green-haze-600: oklch(0.59 0.12 165);
  --green-haze-700: oklch(0.47 0.09 165);
  --green-haze-800: oklch(0.31 0.06 165);
  --green-haze-900: oklch(0.23 0.04 165);

  /* Orange Haze Palette */
  --orange-haze-100: oklch(0.94 0.05 45);
  --orange-haze-200: oklch(0.87 0.10 45);
  --orange-haze-300: oklch(0.79 0.14 45);
  --orange-haze-400: oklch(0.71 0.17 40);
  --orange-haze-500: oklch(0.63 0.20 35);
  --orange-haze-600: oklch(0.52 0.15 35);
  --orange-haze-700: oklch(0.42 0.11 35);
  --orange-haze-800: oklch(0.29 0.07 35);
  --orange-haze-900: oklch(0.22 0.05 35);

  /* Chetwode Palette (Purple/Violet) */
  --chetwode-100: oklch(0.93 0.04 290);
  --chetwode-200: oklch(0.85 0.07 290);
  --chetwode-300: oklch(0.76 0.10 290);
  --chetwode-400: oklch(0.67 0.12 290);
  --chetwode-500: oklch(0.55 0.14 290);
  --chetwode-600: oklch(0.44 0.11 290);
  --chetwode-700: oklch(0.35 0.08 290);
  --chetwode-800: oklch(0.23 0.05 290);
  --chetwode-900: oklch(0.17 0.04 290);

  /* ===========================================
     FIGMA COMPONENT TOKENS (flattened oklch)
     =========================================== */

  /* Text - Button Primary (hex for v0 compatibility) */
  --color-text-button-primary-default: #ffffff;
  --color-text-button-primary-hover: #ffffff;
  --color-text-button-primary-pressed: #ffffff;
  --color-text-button-primary-focused: #ffffff;
  --color-text-button-primary-disabled: #b8bdc2;

  /* Text - Button Secondary (hex for v0 compatibility) */
  --color-text-button-secondary-default: #6d757c;
  --color-text-button-secondary-hover: #7c848b;
  --color-text-button-secondary-pressed: #2a3036;
  --color-text-button-secondary-focused: #4d555c;
  --color-text-button-secondary-disabled: #909aa1;

  /* Text - Button Tertiary (hex for v0 compatibility) */
  --color-text-button-tertiary-default: #0b49ea;
  --color-text-button-tertiary-hover: #0b49ea;
  --color-text-button-tertiary-pressed: #0b49ea;
  --color-text-button-tertiary-focused: #0b49ea;
  --color-text-button-tertiary-disabled: #4d555c;

  /* Text - Button Error (hex for v0 compatibility) */
  --color-text-button-error-default: #ffffff;
  --color-text-button-error-hover: #ffffff;
  --color-text-button-error-pressed: #ffffff;
  --color-text-button-error-focused: #ffffff;
  --color-text-button-error-disabled: #e57a7a;

  /* Surface - Button Primary */
  --color-surface-button-primary-default: oklch(0.45 0.21 264);
  --color-surface-button-primary-hover: oklch(0.40 0.16 264);
  --color-surface-button-primary-pressed: oklch(0.24 0.09 264);
  --color-surface-button-primary-focused: oklch(0.45 0.21 264);
  --color-surface-button-primary-disabled: oklch(0.57 0.01 250);

  /* Surface - Button Secondary */
  --color-surface-button-secondary-default: oklch(1.00 0 0);
  --color-surface-button-secondary-hover: oklch(0.91 0.01 250);
  --color-surface-button-secondary-pressed: oklch(0.88 0.01 250);
  --color-surface-button-secondary-focused: oklch(1.00 0 0);
  --color-surface-button-secondary-disabled: oklch(0.88 0.01 250);

  /* Surface - Button Tertiary */
  --color-surface-button-tertiary-default: oklch(0.96 0.00 264);
  --color-surface-button-tertiary-hover: oklch(0.91 0.01 250);
  --color-surface-button-tertiary-pressed: oklch(0.92 0.05 254);
  --color-surface-button-tertiary-focused: oklch(0.96 0.00 264);
  --color-surface-button-tertiary-disabled: oklch(0.85 0.01 250);

  /* Surface - Dashboard */
  --color-surface-dashboard: var(--grey-150);

  /* Surface - Button Error */
  --color-surface-button-error-default: oklch(0.50 0.19 25);
  --color-surface-button-error-hover: oklch(0.36 0.13 25);
  --color-surface-button-error-pressed: oklch(0.29 0.10 25);
  --color-surface-button-error-focused: oklch(0.50 0.19 25);
  --color-surface-button-error-disabled: oklch(0.95 0.03 25);

  /* Stroke - Button Secondary */
  --color-stroke-button-secondary-default: oklch(0.52 0.01 250);
  --color-stroke-button-secondary-hover: oklch(0.57 0.01 250);
  --color-stroke-button-secondary-pressed: oklch(0.23 0.01 250);
  --color-stroke-button-secondary-focused: oklch(0.45 0.21 264);
  --color-stroke-button-secondary-disabled: oklch(0.65 0.01 250);

  /* Badge - Filled Colors */
  --color-badge-filled-default-bg: oklch(0.93 0.04 290);
  --color-badge-filled-default-text: oklch(0.44 0.11 290);
  --color-badge-filled-sky-bg: oklch(0.94 0.04 230);
  --color-badge-filled-sky-text: oklch(0.43 0.09 230);
  --color-badge-filled-grass-bg: oklch(0.95 0.05 165);
  --color-badge-filled-grass-text: oklch(0.47 0.09 165);
  --color-badge-filled-bored-bg: oklch(0.94 0.05 45);
  --color-badge-filled-bored-text: oklch(0.42 0.11 35);
  --color-badge-filled-negative-bg: oklch(0.98 0.01 25);
  --color-badge-filled-negative-text: oklch(0.50 0.19 25);
  --color-badge-filled-neutral-bg: oklch(0.91 0.01 250);
  --color-badge-filled-neutral-text: oklch(0.23 0.01 250);
  --color-badge-filled-neutral-border: oklch(0.81 0.01 250);
  --color-badge-filled-dark-bg: oklch(0.27 0.01 250);
  --color-badge-filled-dark-text: oklch(1.00 0 0);

  /* Badge - Outline Colors */
  --color-badge-outline-default-border: oklch(0.85 0.07 290);
  --color-badge-outline-default-text: oklch(0.55 0.14 290);
  --color-badge-outline-sky-border: oklch(0.87 0.08 230);
  --color-badge-outline-sky-text: oklch(0.54 0.12 230);
  --color-badge-outline-grass-border: oklch(0.90 0.09 165);
  --color-badge-outline-grass-text: oklch(0.54 0.13 150);
  --color-badge-outline-bored-border: oklch(0.87 0.10 45);
  --color-badge-outline-bored-text: oklch(0.52 0.15 35);
  --color-badge-outline-negative-border: oklch(0.95 0.04 60);
  --color-badge-outline-negative-text: oklch(0.50 0.19 25);
  --color-badge-outline-neutral-border: oklch(0.81 0.01 250);
  --color-badge-outline-neutral-text: oklch(0.23 0.01 250);
  --color-badge-outline-dark-border: oklch(0.27 0.01 250);
  --color-badge-outline-dark-text: oklch(0.27 0.01 250);

  /* ===========================================
     Alert/Callout Component Tokens
     =========================================== */
  /* Info variant - brand blue */
  --color-alert-info-bg: oklch(0.95 0.03 250);
  --color-alert-info-border: oklch(0.85 0.06 250);
  --color-alert-info-icon: oklch(0.45 0.21 264);

  /* Success variant - green */
  --color-alert-success-bg: oklch(0.98 0.02 145);
  --color-alert-success-border: oklch(0.85 0.06 145);
  --color-alert-success-icon: oklch(0.55 0.15 145);

  /* Warning variant - orange */
  --color-alert-warning-bg: oklch(0.99 0.02 70);
  --color-alert-warning-border: oklch(0.85 0.12 50);
  --color-alert-warning-icon: oklch(0.65 0.18 50);

  /* Critical/Destructive variant - red */
  --color-alert-critical-bg: oklch(0.97 0.02 25);
  --color-alert-critical-border: oklch(0.85 0.06 25);
  --color-alert-critical-icon: oklch(0.55 0.20 25);

  /* ===========================================
     Link Component Tokens (hex for v0 compatibility)
     =========================================== */
  --color-text-link-default: #0b49ea;
  --color-text-link-hover: #1a3db8;
  --color-text-link-pressed: #0f2163;
  --color-text-link-visited: #1a3399;
  --color-text-link-disabled: #909aa1;
  --color-icon-brand: oklch(0.45 0.21 264);

  /* ===========================================
     FIGMA DESIGN TOKENS - Numeric (Spacing, Radius, Border)
     =========================================== */

  /* Primitive Pixels */
  --px-1: 1px;
  --px-2: 2px;
  --px-3: 3px;
  --px-4: 4px;
  --px-6: 6px;
  --px-8: 8px;
  --px-12: 12px;
  --px-16: 16px;
  --px-24: 24px;
  --px-32: 32px;
  --px-36: 36px;
  --px-40: 40px;
  --px-48: 48px;
  --px-64: 64px;
  --px-80: 80px;
  --px-96: 96px;

  /* Spacing */
  --spacing-sp-2: var(--px-2);
  --spacing-sp-4: var(--px-4);
  --spacing-sp-6: var(--px-6);
  --spacing-sp-8: var(--px-8);
  --spacing-sp-12: var(--px-12);
  --spacing-sp-16: var(--px-16);
  --spacing-sp-24: var(--px-24);
  --spacing-sp-32: var(--px-32);
  --spacing-sp-36: var(--px-36);
  --spacing-sp-40: var(--px-40);
  --spacing-sp-48: var(--px-48);
  --spacing-sp-64: var(--px-64);
  --spacing-sp-80: var(--px-80);
  --spacing-sp-96: var(--px-96);

  /* Radius */
  --radius-xxs: var(--px-2);
  --radius-xs: var(--px-4);
  --radius-s: var(--px-8);
  --radius-m: var(--px-12);
  --radius-l: var(--px-16);
  --radius-xl: var(--px-24);
  --radius-xxl: var(--px-32);

  /* Border Width */
  --border-width-100: var(--px-1);
  --border-width-200: var(--px-2);
  --border-width-300: var(--px-3);
  --border-width-400: var(--px-4);

  /* ===========================================
     FIGMA DESIGN TOKENS - Typography
     =========================================== */

  /* Font Family */
  --font-family-brand: "Inter", sans-serif;

  /* Font Sizes */
  --font-size-12: 0.75rem;
  --font-size-14: 0.875rem;
  --font-size-16: 1rem;
  --font-size-20: 1.25rem;
  --font-size-24: 1.5rem;
  --font-size-28: 1.75rem;
  --font-size-32: 2rem;

  /* Line Heights */
  --line-height-16: 16px;
  --line-height-20: 20px;
  --line-height-22: 22px;
  --line-height-24: 24px;
  --line-height-28: 28px;
  --line-height-32: 32px;
  --line-height-36: 36px;

  /* Font Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-extrabold: 800;

  /* Body Typography */
  --font-body-small-size: var(--font-size-12);
  --font-body-small-line-height: var(--line-height-16);
  --font-body-small-regular-weight: var(--font-weight-regular);
  --font-body-small-semibold-weight: var(--font-weight-semibold);
  --font-body-small-bold-weight: var(--font-weight-bold);

  --font-body-medium-size: var(--font-size-14);
  --font-body-medium-line-height: var(--line-height-20);
  --font-body-medium-regular-weight: var(--font-weight-regular);
  --font-body-medium-semibold-weight: var(--font-weight-semibold);
  --font-body-medium-bold-weight: var(--font-weight-bold);

  --font-body-large-size: var(--font-size-16);
  --font-body-large-line-height: var(--line-height-24);
  --font-body-large-regular-weight: var(--font-weight-regular);
  --font-body-large-semibold-weight: var(--font-weight-semibold);
  --font-body-large-bold-weight: var(--font-weight-bold);

  /* Headline Typography */
  --font-headline-h1-size: var(--font-size-32);
  --font-headline-h1-line-height: var(--line-height-36);
  --font-headline-h1-weight: var(--font-weight-extrabold);

  --font-headline-h2-size: var(--font-size-28);
  --font-headline-h2-line-height: var(--line-height-32);
  --font-headline-h2-weight: var(--font-weight-extrabold);

  --font-headline-h3-size: var(--font-size-24);
  --font-headline-h3-line-height: var(--line-height-28);
  --font-headline-h3-weight: var(--font-weight-bold);

  --font-headline-h4-size: var(--font-size-20);
  --font-headline-h4-line-height: var(--line-height-24);
  --font-headline-h4-weight: var(--font-weight-bold);

  --font-headline-h5-size: var(--font-size-16);
  --font-headline-h5-line-height: var(--line-height-20);
  --font-headline-h5-weight: var(--font-weight-semibold);

  /* Utility Typography */
  --font-utility-link-size: var(--font-size-14);
  --font-utility-link-line-height: var(--line-height-20);
  --font-utility-link-weight: var(--font-weight-semibold);

  /* ===========================================
     CHECKBOX / CONTROLS TOKENS
     =========================================== */
  --color-stroke-controls-default: oklch(0.74 0.01 250);  /* neutral-450 */
  --color-stroke-controls-hover: oklch(0.23 0.01 250);    /* neutral-1050 */
  --color-stroke-controls-disabled: oklch(0.63 0.01 250); /* neutral-900 */
  --color-surface-controls-selected: oklch(0.45 0.21 264); /* brand-500 */
  --color-surface-controls-hover: oklch(0.40 0.16 264);   /* brand-600 */
  --color-surface-controls-disabled: oklch(0.74 0.01 250); /* neutral-450 */
  --color-surface-controls-locked: oklch(0.74 0.01 250);  /* neutral-450 */
  --color-text-controls-disabled: #8a939a;   /* neutral-900 - hex for v0 */
  --color-surface-focused: oklch(0.85 0.07 254);          /* ring color */

  /* Tooltip tokens */
  --color-surface-tooltip: oklch(0.23 0.01 250);          /* neutral-1000 / foreground-dark */
  --color-text-tooltip: #ffffff;                   /* white / text-inverse - hex for v0 */

  /* ButtonGroup / ToggleGroup tokens */
  --color-surface-button-group-background: oklch(0.93 0.01 250); /* neutral-250 / #e9ecee */
  --color-surface-button-group-hover: oklch(0.96 0.00 250);      /* neutral-200 / #f2f4f5 */
  --color-surface-button-group-active: oklch(1.00 0 0);          /* neutral-50 / white */

  /* Tabs / Tabset tokens */
  --color-stroke-default: oklch(0.79 0.01 250);   /* neutral-450 / #bfc4c8 */
  --color-stroke-brand: oklch(0.45 0.21 264);     /* brand-500 / #0b49ea */
  --color-stroke-dark: oklch(0.20 0.01 250);      /* neutral-1050 / #1c1f22 */

  /* Switch / Toggle tokens */
  --color-surface-toggle-ellipse: oklch(1.00 0 0);       /* neutral-50 / white - thumb color */
  --color-surface-toggle-default: oklch(0.79 0.01 250);  /* neutral-450 / #bfc4c8 - unchecked bg */
  --color-surface-toggle-active: oklch(0.45 0.21 264);   /* brand-500 / #0b49ea - checked bg */
  --color-surface-toggle-focused: oklch(0.80 0.08 254);  /* brand-250 / #bad1f5 - focus ring */
  --color-surface-toggle-disabled: oklch(0.48 0.01 250); /* neutral-750 / #656c70 - disabled bg */

  /* Popover tokens */
  --color-surface-foreground: oklch(1.00 0 0);           /* neutral-50 / white - popover bg */

  /* IconButton tokens */
  --color-icon-dark: oklch(0.20 0.01 250);               /* neutral-1050 / #242e35 - black icon */
  --color-icon-disabled: oklch(0.65 0.01 250);           /* neutral-900 / #3b464f - disabled icon */
  --color-surface-hover: oklch(0.91 0.01 250);           /* neutral-200 / #e5e7e9 - hover bg */
  --color-surface-selected: oklch(0.92 0.04 254);        /* brand-150 / #dde9fa - active/selected bg */

  /* Input tokens (hex for v0 compatibility) */
  --color-text-primary: #1c1f22;            /* neutral-1050 - input value text */
  --color-text-secondary: #656c73;          /* neutral-750 - label, placeholder */
  --color-surface-input-default: oklch(1.00 0 0);        /* neutral-50 / #ffffff - input background */
  --color-surface-input-disabled: oklch(0.91 0.01 250);  /* neutral-300 / #e0e3e6 - disabled background */
  --color-surface-input-locked: oklch(0.88 0.01 250);    /* neutral-350 / #d6dade - read-only background */

  /* State tokens (feedback colors) */
  --color-state-error: oklch(0.50 0.19 25);              /* red-500 / #cc2330 - error accent */
  --color-state-success: oklch(0.52 0.12 145);           /* green-500 / #348347 - success accent */
