  --color-alert-warning-icon: var(--orange-400);
  --color-alert-critical-bg: var(--red-900);
  --color-alert-critical-border: var(--red-700);
  --color-alert-critical-icon: var(--red-400);

  /* ---------- Badges (filled: dark bg + light text) ---------- */
  --color-badge-filled-default-bg: var(--chetwode-800);
  --color-badge-filled-default-text: var(--chetwode-200);
  --color-badge-filled-sky-bg: var(--azure-800);
  --color-badge-filled-sky-text: var(--azure-200);
  --color-badge-filled-grass-bg: var(--green-haze-800);
  --color-badge-filled-grass-text: var(--green-haze-200);
  --color-badge-filled-bored-bg: var(--orange-haze-800);
  --color-badge-filled-bored-text: var(--orange-haze-200);
  --color-badge-filled-negative-bg: var(--red-800);
  --color-badge-filled-negative-text: var(--red-200);
  --color-badge-filled-neutral-bg: var(--grey-900);
  --color-badge-filled-neutral-text: var(--grey-100);
  --color-badge-filled-neutral-border: var(--grey-800);
  --color-badge-filled-dark-bg: var(--grey-200);         /* dark badge inverts to light */
  --color-badge-filled-dark-text: var(--grey-1050);

  /* ---------- Badges (outline) ---------- */
  --color-badge-outline-default-border: var(--chetwode-600);
  --color-badge-outline-default-text: var(--chetwode-300);
  --color-badge-outline-sky-border: var(--azure-600);
  --color-badge-outline-sky-text: var(--azure-300);
  --color-badge-outline-grass-border: var(--green-haze-600);
  --color-badge-outline-grass-text: var(--green-haze-300);
  --color-badge-outline-bored-border: var(--orange-haze-600);
  --color-badge-outline-bored-text: var(--orange-haze-300);
  --color-badge-outline-negative-border: var(--red-600);
  --color-badge-outline-negative-text: var(--red-300);
  --color-badge-outline-neutral-border: var(--grey-800);
  --color-badge-outline-neutral-text: var(--grey-200);
  --color-badge-outline-dark-border: var(--grey-300);
  --color-badge-outline-dark-text: var(--grey-200);
}

/* ===========================================
   SHELL DENSITY TOKENS
   Size-only tokens (identical in light + dark) scoped by the `data-density`
   attribute that the Shell sets on its root. `comfortable` preserves the
   standard BRD scale; `compact` tightens spacing/control/grid sizing for
   high-density personas (Trader/Ops). Consume via var(--shell-density-*).
   =========================================== */
[data-density="comfortable"] {
  --shell-density-gap: var(--spacing-sp-24); /* primary content gap (24px) */
  --shell-density-gap-tight: var(--spacing-sp-16); /* secondary gap (16px) */
  --shell-density-section-gap: var(--spacing-sp-24); /* page section gap */
  --shell-density-control-height: 40px; /* default control height */
  --shell-density-grid-row-height: 40px; /* AG Grid data row */
  --shell-density-grid-header-height: 44px; /* AG Grid header */
  --shell-density-grid-spacing: 8px; /* AG Grid internal spacing */
  --shell-density-chart-spacing: 16px; /* Highcharts chart spacing */
}

[data-density="compact"] {
  --shell-density-gap: var(--spacing-sp-12); /* tighter primary gap (12px) */
  --shell-density-gap-tight: var(--spacing-sp-8); /* tighter secondary gap (8px) */
  --shell-density-section-gap: var(--spacing-sp-16); /* tighter section gap */
  --shell-density-control-height: 32px; /* small control height */
  --shell-density-grid-row-height: 24px; /* dense blotter row (hard cap) */
  --shell-density-grid-header-height: 28px; /* dense grid header */
  --shell-density-grid-spacing: 4px; /* dense AG Grid spacing */
  --shell-density-chart-spacing: 8px; /* tighter Highcharts spacing */
}

@theme inline {
  /* ===========================================
     TAILWIND THEME - Standard shadcn/ui tokens only
     =========================================== */

  /* Core Colors */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* Chart Colors (1-26) */
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-chart-6: var(--chart-6);
  --color-chart-7: var(--chart-7);
  --color-chart-8: var(--chart-8);
  --color-chart-9: var(--chart-9);
  --color-chart-10: var(--chart-10);
  --color-chart-11: var(--chart-11);
  --color-chart-12: var(--chart-12);
  --color-chart-13: var(--chart-13);
  --color-chart-14: var(--chart-14);
  --color-chart-15: var(--chart-15);
  --color-chart-16: var(--chart-16);
  --color-chart-17: var(--chart-17);
  --color-chart-18: var(--chart-18);
  --color-chart-19: var(--chart-19);
  --color-chart-20: var(--chart-20);
  --color-chart-21: var(--chart-21);
  --color-chart-22: var(--chart-22);
  --color-chart-23: var(--chart-23);
  --color-chart-24: var(--chart-24);
  --color-chart-25: var(--chart-25);
  --color-chart-26: var(--chart-26);

  /* Radius */
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);

  /* Sidebar */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Font */
  --font-sans: var(--font-family-brand);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-family-brand);
  }
}

/* Button Loading Animation */
@keyframes flicker {
  0%, 80%, 100% {
    opacity: 0;
  }
  40% {
    opacity: 1;
  }
}
